const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parse the build graph text into a map of task costs and an ordered list
 * of dependency declarations. Throws a CliError for any malformed input,
 * including a reference to a task nobody declared.
 */
export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const tasks = new Map() // name -> cost
  const depDecls = [] // { name, deps, line }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw new CliError(`line ${lineNo}: expected task <name> <cost>`)
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw new CliError(`line ${lineNo}: cost must be a non-negative integer`)
      }
      if (tasks.has(name)) {
        throw new CliError(`line ${lineNo}: task ${name} is declared twice`)
      }
      tasks.set(name, parseInt(costStr, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw new CliError(`line ${lineNo}: expected dep <name> <dependency>...`)
      }
      const name = words[1]
      const deps = words.slice(2)
      if (!NAME_RE.test(name)) {
        throw new CliError(`line ${lineNo}: invalid task name ${name}`)
      }
      for (const dep of deps) {
        if (!NAME_RE.test(dep)) {
          throw new CliError(`line ${lineNo}: invalid task name ${dep}`)
        }
      }
      depDecls.push({ name, deps, line: lineNo })
    } else {
      throw new CliError(`line ${lineNo}: unknown directive ${directive}`)
    }
  }

  // Every name a dep line uses must be declared. Report the first offender
  // in input order.
  for (const decl of depDecls) {
    if (!tasks.has(decl.name)) {
      throw new CliError(`unknown task ${decl.name}`)
    }
    for (const dep of decl.deps) {
      if (!tasks.has(dep)) {
        throw new CliError(`unknown task ${dep}`)
      }
    }
  }

  // Build the dependency adjacency: name -> sorted, deduped dependency names.
  const deps = new Map()
  for (const name of tasks.keys()) deps.set(name, new Set())
  for (const decl of depDecls) {
    const set = deps.get(decl.name)
    for (const dep of decl.deps) set.add(dep)
  }
  const dependencies = new Map()
  for (const [name, set] of deps) {
    dependencies.set(name, [...set].sort())
  }

  return { tasks, dependencies }
}
