/**
 * Find the first cycle a depth-first search discovers, walking tasks in
 * ascending name order and each task's dependencies in ascending name
 * order too. Throws CycleError with the cycle path if one is found.
 */
export function detectCycle(tasks, dependencies) {
  const names = [...tasks.keys()].sort()
  const state = new Map(names.map((n) => [n, 'unvisited'])) // unvisited | active | done
  const stack = []

  function visit(name) {
    state.set(name, 'active')
    stack.push(name)
    for (const dep of dependencies.get(name) || []) {
      const s = state.get(dep)
      if (s === 'active') {
        const idx = stack.indexOf(dep)
        const cycle = stack.slice(idx)
        cycle.push(dep)
        throw new CycleError(cycle)
      } else if (s === 'unvisited') {
        visit(dep)
      }
    }
    stack.pop()
    state.set(name, 'done')
  }

  for (const name of names) {
    if (state.get(name) === 'unvisited') {
      visit(name)
    }
  }
}

/**
 * Compute the start, finish and depth (wave) of every task, given the
 * graph is acyclic. Returns a map name -> { start, finish, depth }.
 */
export function computeSchedule(tasks, dependencies) {
  const result = new Map()

  function compute(name) {
    if (result.has(name)) return result.get(name)
    const deps = dependencies.get(name) || []
    let start = 0
    let depth = 0
    for (const dep of deps) {
      const info = compute(dep)
      if (info.finish > start) start = info.finish
      if (info.depth + 1 > depth) depth = info.depth + 1
    }
    const finish = start + tasks.get(name)
    const info = { start, finish, depth }
    result.set(name, info)
    return info
  }

  for (const name of tasks.keys()) compute(name)
  return result
}

/**
 * Compute the priority of every task: the cost of the longest chain that
 * begins at it and runs forward through its dependents down to a task
 * nothing depends on.
 */
export function computePriorities(tasks, dependencies) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, deps] of dependencies) {
    for (const dep of deps) {
      dependents.get(dep).push(name)
    }
  }

  const priority = new Map()

  function compute(name) {
    if (priority.has(name)) return priority.get(name)
    let best = 0
    for (const child of dependents.get(name)) {
      const p = compute(child)
      if (p > best) best = p
    }
    const value = tasks.get(name) + best
    priority.set(name, value)
    return value
  }

  for (const name of tasks.keys()) compute(name)
  return priority
